# area: narrowing_user
# hypothesis: For a TypeIs[int] guard on an int | str parameter, the else branch narrows to str, while a TypeGuard[int] guard leaves the else branch as int | str, so checkers may disagree on the negative-branch type.
from typing import TypeGuard, TypeIs, assert_type, reveal_type


def is_int_is(v: int | str) -> TypeIs[int]:
    return isinstance(v, int)


def is_int_guard(v: int | str) -> TypeGuard[int]:
    return isinstance(v, int)


def describe_is(v: int | str) -> str:
    if is_int_is(v):
        assert_type(v, int)
        return 'int'
    else:
        assert_type(v, str)
        return 'str'


def describe_guard(v: int | str) -> str:
    if is_int_guard(v):
        reveal_type(v)
        return 'int'
    else:
        reveal_type(v)
        return 'other'


print(describe_is(3), describe_is('x'))
print(describe_guard(3), describe_guard('x'))
